STAGES = ["CORTE", "CONFECCION", "TERMINACION"]


def create_stages_for_existing_lots(apps, schema_editor):
    """Los lotes creados antes de esta historia reciben sus etapas, todas pendientes."""
    Lote = apps.get_model("production", "Lote")
    EtapaLote = apps.get_model("production", "EtapaLote")
    EtapaLote.objects.bulk_create([
        EtapaLote(lote_id=lot_id, etapa=stage, secuencia=number, estado="PENDIENTE")
        for lot_id in Lote.objects.filter(deleted_at__isnull=True).values_list("id", flat=True)
        for number, stage in enumerate(STAGES, start=1)
    ])


